/* The coming-soon field (Caleb, 2026-10-10: "an aura coming soon with some
 * other stuff"). One point of light for every company in YC's public
 * directory drifts across a dusk sky, then gathers into a T and holds,
 * breathing, before it lets go and drifts again. The count comes from the
 * server so the caption and the points can never disagree. */
export default function Soon({ count }: { count: number }) {
  const ref = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const still = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let w = 0;
    let h = 0;
    let dpr = 1;
    const n = count;
    const home = new Float32Array(n * 2);
    const goal = new Float32Array(n * 2);
    const seed = new Float32Array(n);
    const pink = Math.floor(n * 0.37);

    function layout() {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      w = canvas!.clientWidth;
      h = canvas!.clientHeight;
      canvas!.width = Math.round(w * dpr);
      canvas!.height = Math.round(h * dpr);
      ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
      // The T: a bar and a stem, sized to the short side so it reads on a
      // phone held upright as well as a wide screen.
      const s = Math.min(w, h) * 0.42;
      const cx = w * (w > 760 ? 0.68 : 0.5);
      const cy = h * (w > 760 ? 0.5 : 0.36);
      const bar = s * 1.1;
      const thick = s * 0.2;
      for (let i = 0; i < n; i++) {
        seed[i] = Math.random();
        home[i * 2] = Math.random() * w;
        home[i * 2 + 1] = Math.random() * h;
        const onBar = i % 5 < 2;
        if (onBar) {
          goal[i * 2] = cx - bar / 2 + Math.random() * bar;
          goal[i * 2 + 1] = cy - s / 2 + Math.random() * thick;
        } else {
          goal[i * 2] = cx - thick / 2 + Math.random() * thick;
          goal[i * 2 + 1] = cy - s / 2 + thick + Math.random() * (s - thick);
        }
      }
    }

    const ease = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
    // One 16 s cycle: drift 5 s, gather 3 s, hold 5 s, release 3 s.
    function gather(t: number) {
      const c = (t / 1000) % 16;
      if (c < 5) return 0;
      if (c < 8) return ease((c - 5) / 3);
      if (c < 13) return 1;
      return 1 - ease((c - 13) / 3);
    }

    let raf = 0;
    let visible = true;
    function frame(now: number) {
      const g = still ? 1 : gather(now);
      ctx!.clearRect(0, 0, w, h);
