        const dy = Math.cos(now / 1000 * (0.1 + k * 0.17) + k * 23) * 14;
        const x = home[i * 2] + dx + (goal[i * 2] - home[i * 2] - dx) * g;
        const y = home[i * 2 + 1] + dy + (goal[i * 2 + 1] - home[i * 2 + 1] - dy) * g;
        const tw = 0.45 + 0.55 * Math.abs(Math.sin(now / 1000 * (0.6 + k) + k * 9));
        const a = (0.35 + 0.65 * g) * tw;
