    raf = requestAnimationFrame(frame);
    const onResize = () => {
      layout();
      if (still) requestAnimationFrame(frame);
    };
    const onVis = () => {
      visible = document.visibilityState === "visible";
      if (visible && !still) raf = requestAnimationFrame(frame);
    };
