    messages: [{ role: "user", content: updates.map((u) => `- ${u}`).join("\n") }],
  });
  const line = textOf(message).split("\n")[0].replace(/^["'“]|["'”.]$/g, "").replace(/\bCHW-\d+\b/gi, "").replace(/\s+/g, " ").trim();
  return line.slice(0, 80) || null;
